const r = await tools.rubrics.get({ rubricRef: 'goal-mode-e2e' });
const rub = (r.results && r.results[0] && r.results[0].rubric) || r.rubric;
const keys = (rub.criteria || []).map(c => c.key);

const sc = await tools.scorecards.list({ rubricRef: 'goal-mode-e2e', limit: 5 });
const rows = sc.scorecards || sc.results || sc.rows || [];
const latest = rows[0];
const ratings = (latest && (latest.ratings || (latest.observation && latest.observation.ratings))) || {};

return {
  rubricCriteriaCount: keys.length,
  rubricKeys: keys,
  latestId: latest && (latest.issueId || latest.id || latest.feature_id),
  latestCreatedAt: latest && (latest.createdAt || latest.created_at),
  inventory: keys.map(k => ({
    key: k,
    rating: ratings[k] ? ratings[k].rating : '<<MISSING>>',
    evidenceChars: ratings[k] && ratings[k].evidence ? ratings[k].evidence.length : 0,
  })),
  ratingKeysNotInRubric: Object.keys(ratings).filter(k => !keys.includes(k)),
};
